use hec_native_ic::{poly::Poly,jac::{Curve,Div}};
#[derive(Clone,Debug)]pub struct Certificate{pub out:Div,pub fallback:bool,pub reduced:bool,pub w:Poly,pub qa:Poly,pub qb:Poly,pub qc:Poly,pub gamma:u64}
pub fn build(c:&Curve,a:&Div,b:&Div)->Certificate{let f=&c.fp;let mut result=Certificate{out:c.zero(),fallback:true,reduced:false,w:Poly::zero(),qa:Poly::zero(),qb:Poly::zero(),qc:Poly::zero(),gamma:1};if c.is_zero(a)||c.is_zero(b){result.out=c.add(a,b);return result}let(d1,e1,e2)=Poly::xgcd(&a.u,&b.u,f);let(d,c1,c2)=Poly::xgcd(&d1,&a.v.add(&b.v,f),f);if d.deg()!=0{result.out=c.add(a,b);return result}let s1=c1.mul(&e1,f);let s2=c1.mul(&e2,f);let u=a.u.mul(&b.u,f);let w=s1.mul(&a.u,f).mul(&b.v,f).add(&s2.mul(&b.u,f).mul(&a.v,f),f).add(&c2.mul(&a.v.mul(&b.v,f).add(&c.f,f),f),f).rem(&u,f);result.out=c.reduce(u,w);result.fallback=false;result.reduced=u.deg()>c.g as isize;result.w=w;result.qa=w.sub(&a.v,f).div_exact(&a.u,f);result.qb=w.sub(&b.v,f).div_exact(&b.u,f);if result.reduced{result.gamma=c.f.sub(&w.mul(&w,f),f).lc();result.qc=w.add(&result.out.v,f).div_exact(&result.out.u,f);}result}
// Inputs must already be verified valid reduced divisors.
pub fn verify(c:&Curve,a:&Div,b:&Div,p:&Certificate)->bool{let f=&c.fp;if c.g!=2{return false}if p.fallback{return p.out==c.add(a,b)&&c.is_valid(&p.out)}if p.out.u.lc()!=1||p.out.u.deg()<0||p.out.u.deg()>2||p.out.v.deg()>=p.out.u.deg(){return false}let u=a.u.mul(&b.u,f);if p.reduced!=(u.deg()>2)||p.w.deg()>=u.deg(){return false}if p.w.sub(&a.v,f)!=p.qa.mul(&a.u,f)||p.w.sub(&b.v,f)!=p.qb.mul(&b.u,f){return false}if p.reduced{if p.gamma==0||p.gamma>=f.p{return false}c.f.sub(&p.w.mul(&p.w,f),f)==u.mul(&p.out.u,f).scale(p.gamma,f)&&p.w.add(&p.out.v,f)==p.qc.mul(&p.out.u,f)}else{p.out.u==u&&p.out.v==p.w&&c.is_valid(&p.out)}}
